import React, { useState } from "react";
import TaskList from "./components/TaskList";
import { Line } from "react-chartjs-2";
import { Chart as ChartJS } from "chart.js/auto";

function App() {
  const [tasks, setTasks] = useState([]);
  const [task, setTask] = useState("");
  const [selectedQuadrant, setSelectedQuadrant] = useState(1);

  const addTask = () => {
    const newTask = {
      id: Date.now(),
      text: task,
      quadrant: selectedQuadrant,
      timer: 0,
      completed: false,
    };
    setTasks([...tasks, newTask]);
    setTask("");
  };

  const deleteTask = (taskId) => {
    setTasks(tasks.filter((t) => t.id !== taskId));
  };

  const toggleTaskCompletion = (taskId) => {
    setTasks(
      tasks.map((t) =>
        t.id === taskId ? { ...t, completed: !t.completed } : t
      )
    );
  };

  const startTimer = (taskId) => {
    setTasks(
      tasks.map((t) =>
        t.id === taskId ? { ...t, timer: Date.now() } : t
      )
    );
  };

  const stopTimer = (taskId) => {
    const taskToUpdate = tasks.find((t) => t.id === taskId);
    if (taskToUpdate) {
      const duration = (Date.now() - taskToUpdate.timer) / 1000; // seconds
      setTasks(
        tasks.map((t) =>
          t.id === taskId ? { ...t, timer: duration } : t
        )
      );
    }
  };

  const chartData = {
    labels: tasks.map((t) => t.text),
    datasets: [
      {
        label: "Task Duration (seconds)",
        data: tasks.map((t) => t.timer),
        borderColor: "rgba(75, 192, 192, 1)",
        backgroundColor: "rgba(75, 192, 192, 0.2)",
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="App">
      <h1>Eisenhower Matrix</h1>

      {/* Task Input */}
      <input
        type="text"
        value={task}
        onChange={(e) => setTask(e.target.value)}
        placeholder="Enter Task"
      />

      {/* Eisenhower Matrix Table for Selecting Quadrant */}
      <table className="matrix-table">
        <tbody>
          <tr>
            <td
              className={`quadrant ${selectedQuadrant === 1 ? "selected" : ""}`}
              onClick={() => setSelectedQuadrant(1)}
            >
              <strong>Important & Urgent</strong>
            </td>
            <td
              className={`quadrant ${selectedQuadrant === 2 ? "selected" : ""}`}
              onClick={() => setSelectedQuadrant(2)}
            >
              <strong>Important & Not Urgent</strong>
            </td>
          </tr>
          <tr>
            <td
              className={`quadrant ${selectedQuadrant === 3 ? "selected" : ""}`}
              onClick={() => setSelectedQuadrant(3)}
            >
              <strong>Not Important & Urgent</strong>
            </td>
            <td
              className={`quadrant ${selectedQuadrant === 4 ? "selected" : ""}`}
              onClick={() => setSelectedQuadrant(4)}
            >
              <strong>Not Important & Not Urgent</strong>
            </td>
          </tr>
        </tbody>
      </table>

      <button onClick={addTask}>Add Task</button>

      {/* Task Lists Displayed by Quadrant */}
      <div className="matrix">
        {[1, 2, 3, 4].map((quadrant) => (
          <TaskList
            key={quadrant}
            quadrant={quadrant}
            tasks={tasks.filter((t) => t.quadrant === quadrant)}
            deleteTask={deleteTask}
            toggleTaskCompletion={toggleTaskCompletion}
            startTimer={startTimer}
            stopTimer={stopTimer}
          />
        ))}
      </div>

      {/* Task Duration Chart */}
      <Line data={chartData} />
    </div>
  );
}

export default App;
